from typing import List

def countPathsWithXorValue(grid: List[List[int]], k: int) -> int:
    m, n = len(grid), len(grid[0])
    MOD = 10**9 + 7
    # dp[i][j] is a list/dictionary of {xor_sum: count}
    # Since grid values are < 16, XOR sum won't exceed 15 (or 31 depending on bit depth)
    # Given constraints say grid[r][c] < 16 and k < 16, max xor is small.
    dp = [[{} for _ in range(n)] for _ in range(m)]

    dp[0][0][grid[0][0]] = 1

    for i in range(m):
        for j in range(n):
            current_map = dp[i][j]
            if not current_map: continue

            # Move Right
            if j + 1 < n:
                target_val = grid[i][j+1]
                target_map = dp[i][j+1]
                for xor_sum, count in current_map.items():
                    new_xor = xor_sum ^ target_val
                    target_map[new_xor] = (target_map.get(new_xor, 0) + count) % MOD

            # Move Down
            if i + 1 < m:
                target_val = grid[i+1][j]
                target_map = dp[i+1][j]
                for xor_sum, count in current_map.items():
                    new_xor = xor_sum ^ target_val
                    target_map[new_xor] = (target_map.get(new_xor, 0) + count) % MOD

    return dp[m-1][n-1].get(k, 0)
