from typing import List

def numberOfComponents(properties: List[List[int]], k: int) -> int:
    n = len(properties)
    # 將每個子列表轉為 set 以方便計算交集中的不重複元素數量
    property_sets = [set(p) for p in properties]

    # 使用鄰接表表示圖
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            # 計算交集中不重複元素的數量
            if len(property_sets[i] & property_sets[j]) >= k:
                adj[i].append(j)
                adj[j].append(i)

    visited = [False] * n
    components = 0

    # 使用 BFS/DFS 遍歷尋找連通分量
    for i in range(n):
        if not visited[i]:
            components += 1
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)

    return components
