def minValidStrings(words: List[str], target: str) -> int:
    # Build a Trie of all prefixes (effectively just storing all words in a set is enough 
    # because any prefix of a word is valid. Actually, we need to know if target[i:j] 
    # is a prefix of ANY word.)
    # A string x is valid if it's a prefix of some word[k].
    # This means for every i, we want the largest j such that target[i:j] is a prefix.

    # Optimization: Just store all words in a Trie to check prefixes quickly.
    trie = {}
    for w in words:
        curr = trie
        for char in w:
            if char not in curr:
                curr[char] = {}
            curr = curr[char]

    n = len(target)
    # dp[i] is the min valid strings to form target[:i]
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(n):
        if dp[i] == float('inf'):
            continue

        # From index i, find all possible prefixes of words that match target[i:]
        curr = trie
        for j in range(i, n):
            char = target[j]
            if char in curr:
                curr = curr[char]
                dp[j + 1] = min(dp[j + 1], dp[i] + 1)
            else:
                break

    return dp[n] if dp[n] != float('inf') else -1
