import collections
from typing import List

def maxSubstringLength(s: str, k: int) -> bool:
    n = len(s)
    if k == 0:
        return True

    first_pos = {}
    last_pos = {}
    for idx, char in enumerate(s):
        if char not in first_pos:
            first_pos[char] = idx
        last_pos[char] = idx

    intervals = []
    # We need to find all minimal special substrings. 
    # A substring s[i:j+1] is special if for every char c in it,
    # first_pos[c] >= i and last_pos[c] <= j, AND the substring is not the whole string.
    # To do this efficiently: for a fixed start i, as we increase j, 
    # the set of characters grows. A special substring [i, j] must satisfy 
    # max(last_pos[c]) for all c in s[i:j+1] == j.
    for i in range(n):
        min_f = n
        max_l = -1
        seen = set()
        for j in range(i, n):
            char = s[j]
            if char not in seen:
                if first_pos[char] < i:
                    break
                seen.add(char)
                if first_pos[char] < min_f:
                    min_f = first_pos[char]
                if last_pos[char] > max_l:
                    max_l = last_pos[char]

            if max_l == j:
                # The substring is s[i : j+1]
                if not (i == 0 and j == n - 1):
                    intervals.append((j, i))
                    break
        # Optimization: if we already found a special substring for this start i,
        # any longer substring starting at i won't be "minimal" in terms of end position.
        # The greedy choice is the one that ends earliest.

    if not intervals:
        return False

    intervals.sort()
    count = 0
    last_end = -1
    for end, start in intervals:
        if start > last_end:
            count += 1
            last_end = end

    return count >= k

